mapper.select:
select '流程中' as workStatus , wft.TOTLE_TRADE_ID as tradeId, wft.SETTLE_DATE as settleDate, fp.FINPROD_NAME as prodName, wft.PORTFOLIO_ID as prodId, wft.TRADE_AMT as tradeAmt, null as portfolioId, null as portfolioName, null as allotAmt, wft.WORKFLOW_ID as workflowId, '02' hasChildren, CONCAT('流程中',IFNULL(wft.PORTFOLIO_ID,'null')) childInfo, 'root' parentInfo, wft.ccy as ccy from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL wft left join WFL_PA_TRD_FIN_DEAL_TOTAl wdt on wdt.TOTLE_TRADE_ID=wft.TOTLE_TRADE_ID left join WFL_TRD_PRODUCT_DEAL wpt on wpt.TOTLE_TRADE_ID=wft.TOTLE_TRADE_ID left join WFL_TRD_PRODUCT_DEAL_ADD wta on wta.TRADE_ID=wpt.TRADE_ID inner join PTL_PORTFOLIO ptp on ptp.PORTFOLIO_ID=wta.PORTFOLIO_ID inner join FIN_PRODUCT_ADD fpa on fpa.PORTFOLIO_ID=wft.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1 AND FINPROD_TYPE2=#{finprodType2}
and FINPROD_MARKET_ID in (
#{item}
)
) fp on fp.FINPROD_ID=fpa.FINPROD_ID where wft.BUSI_TYPE=#{busiType} and wft.FINPROD_TYPE2=#{finprodType2} and wdt.PA_BUSS_TYPE=#{paBusiType} and wft.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} )
and wft.SETTLE_DATE >= STR_TO_DATE(#{vdateStart},'%Y-%m-%d')
and wft.SETTLE_DATE <= STR_TO_DATE(#{vdateEnd},'%Y-%m-%d')
and wft.IS_CANCEL !=#{isCancel} and wft.TRADE_STATUS=#{tardeStatus} group by wft.TOTLE_TRADE_ID,wft.SETTLE_DATE,fp.FINPROD_NAME, wft.PORTFOLIO_ID,wft.TRADE_AMt,wft.WORKFLOW_ID,wft.ccy
union all
select null as workStatus , null as tradeId, null as settleDate, null as prodName, null as prodId, null as tradeAmt, wta.PORTFOLIO_ID as portfolioId, ptp.PORTFOLIO_NAME as portfolioName, (CASE WHEN wpt.ps =#{ps} THEN -1*wpt.TRADE_AMT ELSE wpt.TRADE_AMT END) as allotAmt, null as workflowId, '01' hasChildren, CONCAT(CONCAT('流程中',IFNULL(wft.PORTFOLIO_ID,'null')),wft.TOTLE_TRADE_ID) childInfo, CONCAT('流程中',IFNULL(wft.PORTFOLIO_ID,'null')) parentInfo, null as ccy from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL wft left join WFL_PA_TRD_FIN_DEAL_TOTAl wdt on wdt.TOTLE_TRADE_ID=wft.TOTLE_TRADE_ID left join WFL_TRD_PRODUCT_DEAL wpt on wpt.TOTLE_TRADE_ID=wft.TOTLE_TRADE_ID left join WFL_TRD_PRODUCT_DEAL_ADD wta on wta.TRADE_ID=wpt.TRADE_ID inner join PTL_PORTFOLIO ptp on ptp.PORTFOLIO_ID=wta.PORTFOLIO_ID inner join FIN_PRODUCT_ADD fpa on fpa.PORTFOLIO_ID=wft.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1 AND FINPROD_TYPE2=#{finprodType2}
and FINPROD_MARKET_ID in (
#{item}
)
) fp on fp.FINPROD_ID=fpa.FINPROD_ID where wft.BUSI_TYPE=#{busiType} and wft.FINPROD_TYPE2=#{finprodType2} and wdt.PA_BUSS_TYPE=#{paBusiType} and wft.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} )
and wft.SETTLE_DATE >= STR_TO_DATE(#{vdateStart},'%Y-%m-%d')
and wft.SETTLE_DATE <= STR_TO_DATE(#{vdateEnd},'%Y-%m-%d')
and wft.IS_CANCEL !=#{isCancel} and wft.TRADE_STATUS=#{tardeStatus}

select '有效' as workStatus, tft.TOTLE_TRADE_ID as tradeId, tft.SETTLE_DATE as settleDate, fp.FINPROD_NAME as prodName, fp.FINPROD_MARKET_ID as prodId, tft.TRADE_AMT as tradeAmt, null as portfolioId, null as portfolioName, null as allotAmt, '02' hasChildren, CONCAT(CONCAT('有效',IFNULL(fp.FINPROD_MARKET_ID,'null')),tft.TOTLE_TRADE_ID ) childInfo, 'root' parentInfo, tft.ccy ccy
from TRD_FIN_PRODUCT_DEAL_TOTAL tft
LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL wdt ON wdt.totle_trade_id=tft.totle_trade_id LEFT JOIN TRD_PRODUCT_DEAL tpd ON tft.TOTLE_TRADE_ID=tpd.TOTLE_TRADE_ID left join TRD_PRODUCT_DEAL_ADD tpa on tpa.TRADE_ID=tpd.TRADE_ID inner join PTL_PORTFOLIO ptp on ptp.PORTFOLIO_ID=tpa.PORTFOLIO_ID inner join FIN_PRODUCT_ADD fpa on fpa.PORTFOLIO_ID=tft.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1 AND FINPROD_TYPE2=#{finprodType2}
and FINPROD_MARKET_ID in (
#{item}
)
) fp on fp.FINPROD_ID=fpa.FINPROD_ID where tft.BUSI_TYPE=#{busiType} and tft.FINPROD_TYPE2=#{finprodType2} and wdt.PA_BUSS_TYPE =#{paBusiType} and tft.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} )
and tft.SETTLE_DATE >= STR_TO_DATE(#{vdateStart},'%Y-%m-%d')
and tft.SETTLE_DATE <= STR_TO_DATE(#{vdateEnd},'%Y-%m-%d')
and tft.IS_CANCEL !=#{isCancel} group by tft.TOTLE_TRADE_ID,tft.SETTLE_DATE,fp.FINPROD_NAME,fp.FINPROD_MARKET_ID,tft.TRADE_AMt,tft.ccy union all select null as workStatus, null as tradeId, null as settleDate, null as prodName, null as prodId, null as tradeAmt, tpa.PORTFOLIO_ID as portfolioId, ptp.PORTFOLIO_NAME as portfolioName, (CASE WHEN tpd.ps =#{ps} THEN -1*tpd.TRADE_AMT ELSE tpd.TRADE_AMT END) as allotAmt, '01' hasChildren, CONCAT('有效',IFNULL(fp.FINPROD_MARKET_ID,'null')) childInfo, CONCAT(CONCAT('有效',IFNULL(fp.FINPROD_MARKET_ID,'null')),tft.TOTLE_TRADE_ID ) parentInfo, null as ccy from TRD_FIN_PRODUCT_DEAL_TOTAL tft
LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL wdt ON wdt.totle_trade_id=tft.totle_trade_id LEFT JOIN TRD_PRODUCT_DEAL tpd ON tft.TOTLE_TRADE_ID=tpd.TOTLE_TRADE_ID left join TRD_PRODUCT_DEAL_ADD tpa on tpa.TRADE_ID=tpd.TRADE_ID inner join PTL_PORTFOLIO ptp on ptp.PORTFOLIO_ID=tpa.PORTFOLIO_ID inner join FIN_PRODUCT_ADD fpa on fpa.PORTFOLIO_ID=tft.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1 AND FINPROD_TYPE2=#{finprodType2}
and FINPROD_MARKET_ID in (
#{item}
)
) fp on fp.FINPROD_ID=fpa.FINPROD_ID where tft.BUSI_TYPE=#{busiType} and tft.FINPROD_TYPE2=#{finprodType2} and wdt.PA_BUSS_TYPE =#{paBusiType} and tft.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} )
and tft.SETTLE_DATE >= STR_TO_DATE(#{vdateStart},'%Y-%m-%d')
and tft.SETTLE_DATE <= STR_TO_DATE(#{vdateEnd},'%Y-%m-%d')
and tft.IS_CANCEL !=#{isCancel}

select T.workStatus, T.settleDate, T.prodName, T.prodId, sum(T.tradeAmt) tradeAmt, T.portfolioId, T.portfolioName, T.ccy, T.allotAmt, T.hasChildren, T.childInfo, T.parentInfo, T.otherPortfolioId from (select '待处理' as workStatus, null as tradeId , STR_TO_DATE(#{platDate},'%Y-%m-%d') as settleDate, fp.FINPROD_NAME as prodName, fp.FINPROD_MARKET_ID as prodId, pcp.AMOUNT as tradeAmt, null as portfolioId, null as portfolioName, pcp.CCY as ccy, null as allotAmt, '02' hasChildren, CONCAT('待处理',IFNULL(fp.FINPROD_MARKET_ID,'null')) childInfo, 'root' parentInfo, pcp.PORTFOLIO_ID otherPortfolioId from PTL_CASH_POSITION_FLOW pcp inner join PTL_CAPACCT_INFO pci on pci.PORTFOLIO_ID=pcp.PORTFOLIO_ID and pci.CCY=pcp.CCY and pci.ACCT_NO=pcp.ACCT_ID and pci.ACCT_TYPE=#{acctType} inner join FIN_PRODUCT_ADD fpa on pcp.PORTFOLIO_ID=fpa.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1
and FINPROD_MARKET_ID in (
#{item}
)
) fp on fp.FINPROD_ID=fpa.FINPROD_ID and fp.FINPROD_TYPE2 not in (#{dfinprodType2}) inner join PTL_PORTFOLIO ptp on pcp.PORTFOLIO_ID=ptp.PARENT_PORTFOLIO_ID where pcp.HODING_TYPE=#{hodingType} and pcp.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} )
and pcp.SPLIT_TYPE=#{splitType} or pcp.SPLIT_TYPE is null and fp.FINPROD_MARKET_ID not in( select wft.PORTFOLIO_ID as prodId from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL wft left join WFL_PA_TRD_FIN_DEAL_TOTAl wdt on wdt.TOTLE_TRADE_ID=wft.TOTLE_TRADE_ID left join WFL_TRD_PRODUCT_DEAL wpt on wpt.TOTLE_TRADE_ID=wft.TOTLE_TRADE_ID left join WFL_TRD_PRODUCT_DEAL_ADD wta on wta.TRADE_ID=wpt.TRADE_ID inner join PTL_PORTFOLIO ptp on ptp.PORTFOLIO_ID=wta.PORTFOLIO_ID inner join FIN_PRODUCT_ADD fpa on fpa.PORTFOLIO_ID=wft.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1 AND FINPROD_TYPE2=#{finprodType2}
and FINPROD_MARKET_ID in (
#{item}
)
) fp on fp.FINPROD_ID=fpa.FINPROD_ID where wft.BUSI_TYPE=#{busiType} and wft.FINPROD_TYPE2=#{finprodType2} and wdt.PA_BUSS_TYPE=#{paBusiType} and wft.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} )
and wft.SETTLE_DATE >= STR_TO_DATE(#{vdateStart},'%Y-%m-%d')
and wft.SETTLE_DATE <= STR_TO_DATE(#{vdateEnd},'%Y-%m-%d')
and wft.IS_CANCEL !=#{isCancel} and wft.TRADE_STATUS=#{tardeStatus} group by wft.TOTLE_TRADE_ID,wft.SETTLE_DATE,fp.FINPROD_NAME, wft.PORTFOLIO_ID,wft.TRADE_AMt,wft.WORKFLOW_ID ) group by fp.FINPROD_NAME,fp.FINPROD_MARKET_ID, pcp.CCY,pcp.AMOUNT,pcp.seqNo ,pcp.PORTFOLIO_ID ) T group by T.prodName,T.prodId,T.CCY,T.otherPortfolioId,T.childInfo, T.workStatus, T.settleDate,T.hasChildren, T.parentInfo,T.allotAmt

select null as workStatus, null as tradeId , null as settleDate, null as prodName, null as prodId, null as tradeAmt, ptp.PORTFOLIO_ID as portfolioId, ptp.PORTFOLIO_NAME as portfolioName, null as ccy, null as allotAmt, null as seqNo, '01' hasChildren, CONCAT(CONCAT('待处理',IFNULL(fp.FINPROD_MARKET_ID,'null')),ptp.PORTFOLIO_ID) childInfo, CONCAT('待处理',IFNULL(fp.FINPROD_MARKET_ID,'null')) parentInfo from PTL_CASH_POSITION_FLOW pcp inner join PTL_CAPACCT_INFO pci on pci.PORTFOLIO_ID=pcp.PORTFOLIO_ID and pci.CCY=pcp.CCY and pci.ACCT_NO=pcp.ACCT_ID and pci.ACCT_TYPE=#{acctType} inner join FIN_PRODUCT_ADD fpa on pcp.PORTFOLIO_ID=fpa.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1
and FINPROD_MARKET_ID in (
#{item}
)
) fp on fp.FINPROD_ID=fpa.FINPROD_ID and fp.FINPROD_TYPE2 not in (#{dfinprodType2}) inner join PTL_PORTFOLIO ptp on pcp.PORTFOLIO_ID=ptp.PARENT_PORTFOLIO_ID where pcp.HODING_TYPE=#{hodingType} and pcp.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} ) and pcp.SPLIT_TYPE=#{splitType} or pcp.SPLIT_TYPE is null group by fp.FINPROD_NAME,fp.FINPROD_MARKET_ID,ptp.PORTFOLIO_ID, ptp.PORTFOLIO_NAME

select '流程中' as workStatus , wft.TOTLE_TRADE_ID as tradeId, wft.SETTLE_DATE as settleDate, fp.FINPROD_NAME as prodName, wft.PORTFOLIO_ID as prodId, wft.TRADE_AMT as tradeAmt, wta.PORTFOLIO_ID as portfolioId, ptp.PORTFOLIO_NAME as portfolioName, null as ccy, wpt.TRADE_AMT as allotAmt, null as seqNo, wft.WORKFLOW_ID as workflowId, '01' hasChildren, CONCAT(IFNULL(wft.PORTFOLIO_ID,'null'),'') childInfo, 'root' parentInfo from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL wft left join WFL_PA_TRD_FIN_DEAL_TOTAl wdt on wdt.TOTLE_TRADE_ID=wft.TOTLE_TRADE_ID left join WFL_TRD_PRODUCT_DEAL wpt on wpt.TOTLE_TRADE_ID=wft.TOTLE_TRADE_ID left join WFL_TRD_PRODUCT_DEAL_ADD wta on wta.TRADE_ID=wpt.TRADE_ID left join PTL_PORTFOLIO ptp on ptp.PORTFOLIO_ID=wta.PORTFOLIO_ID inner join FIN_PRODUCT_ADD fpa on fpa.PORTFOLIO_ID=wft.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1
and FINPROD_MARKET_ID in (
#{item}
)
) fp on fp.FINPROD_ID=fpa.FINPROD_ID where wft.BUSI_TYPE=#{busiType} and wft.FINPROD_TYPE2=#{finprodType2} and wdt.PA_BUSS_TYPE=#{paBusiType} and wft.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} )
and wft.SETTLE_DATE >= STR_TO_DATE(#{vdateStart},'%Y-%m-%d')
and wft.SETTLE_DATE <= STR_TO_DATE(#{vdateEnd},'%Y-%m-%d')
and wft.IS_CANCEL !=#{isCancel} and wft.TRADE_STATUS=#{tardeStatus} union all select '有效' as workStatus, tft.TOTLE_TRADE_ID as tradeId, tft.SETTLE_DATE as settleDate, fp.FINPROD_NAME as prodName, fp.FINPROD_MARKET_ID as prodId, tft.TRADE_AMT as tradeAmt, tpa.PORTFOLIO_ID as portfolioId, ptp.PORTFOLIO_NAME as portfolioName, null as ccy, tpd.TRADE_AMT as allotAmt, null as seqNo, null as workflowId, '01' hasChildren, CONCAT(IFNULL(fp.FINPROD_MARKET_ID,'null'),'') childInfo, 'root' parentInfo from TRD_FIN_PRODUCT_DEAL_TOTAL tft
LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL wdt ON wdt.totle_trade_id=tft.totle_trade_id LEFT JOIN TRD_PRODUCT_DEAL tpd ON tft.TOTLE_TRADE_ID=tpd.TOTLE_TRADE_ID left join TRD_PRODUCT_DEAL_ADD tpa on tpa.TRADE_ID=tpd.TRADE_ID left join PTL_PORTFOLIO ptp on ptp.PORTFOLIO_ID=tpa.PORTFOLIO_ID inner join FIN_PRODUCT_ADD fpa on fpa.PORTFOLIO_ID=tft.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1
and FINPROD_MARKET_ID in (
#{item}
)
) fp on fp.FINPROD_ID=fpa.FINPROD_ID where tft.BUSI_TYPE=#{busiType} and tft.FINPROD_TYPE2=#{finprodType2} and wdt.PA_BUSS_TYPE =#{paBusiType} and tft.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} )
and tft.TRADE_DATE >= STR_TO_DATE(#{vdateStart},'%Y-%m-%d')
and tft.TRADE_DATE <= STR_TO_DATE(#{vdateEnd},'%Y-%m-%d')
and tft.IS_CANCEL !=#{isCancel}
